CREATE TABLE public.login_challenges(id uuid PRIMARY KEY DEFAULT gen_random_uuid(), user_id uuid NOT NULL REFERENCES public.profiles(id), token_hash text NOT NULL UNIQUE, expires_at timestamptz NOT NULL, used_at timestamptz);
GRANT ALL ON public.login_challenges TO service_role; ALTER TABLE public.login_challenges ENABLE ROW LEVEL SECURITY;
CREATE TABLE public.verified_sessions(session_id uuid PRIMARY KEY, user_id uuid NOT NULL REFERENCES public.profiles(id), verified_at timestamptz NOT NULL DEFAULT now(), expires_at timestamptz NOT NULL);
GRANT SELECT ON public.verified_sessions TO authenticated; GRANT ALL ON public.verified_sessions TO service_role; ALTER TABLE public.verified_sessions ENABLE ROW LEVEL SECURITY;
CREATE POLICY own_session ON public.verified_sessions FOR SELECT TO authenticated USING(user_id=auth.uid());
CREATE OR REPLACE FUNCTION public.otp_verified() RETURNS boolean LANGUAGE sql STABLE SECURITY DEFINER SET search_path=public AS $$ SELECT EXISTS(SELECT 1 FROM public.verified_sessions WHERE user_id=auth.uid() AND session_id=(auth.jwt()->>'session_id')::uuid AND expires_at>now()) $$;
CREATE FUNCTION public.finish_login(challenge_hash text, uid uuid, sid uuid, expires timestamptz) RETURNS boolean LANGUAGE plpgsql SECURITY DEFINER SET search_path=public AS $$ DECLARE cid uuid; BEGIN UPDATE public.login_challenges SET used_at=now() WHERE token_hash=challenge_hash AND user_id=uid AND used_at IS NULL AND expires_at>now() RETURNING id INTO cid; IF cid IS NULL THEN RETURN false; END IF; INSERT INTO public.verified_sessions(session_id,user_id,expires_at) VALUES(sid,uid,expires) ON CONFLICT(session_id) DO UPDATE SET expires_at=excluded.expires_at; RETURN true; END $$;
REVOKE ALL ON FUNCTION public.finish_login(text,uuid,uuid,timestamptz) FROM PUBLIC; GRANT EXECUTE ON FUNCTION public.finish_login(text,uuid,uuid,timestamptz) TO service_role;
REVOKE ALL ON FUNCTION public.create_ironhaus_profile(),public.sync_profile_email(),public.client_gym_link() FROM PUBLIC;
REVOKE ALL ON FUNCTION public.gym_access(uuid,text),public.is_super_admin(),public.can_read_image(text),public.otp_verified() FROM PUBLIC;
GRANT EXECUTE ON FUNCTION public.gym_access(uuid,text),public.is_super_admin(),public.can_read_image(text),public.otp_verified() TO authenticated;